return ['domain'=>'pnscripts-price-history','plural-forms'=>'nplurals=3; plural=(n==1 ? 0 : n%10>=2 && n%10<=4 && (n%100<12 || n%100>14) ? 1 : 2);','language'=>'pl_PL','project-id-version'=>'PN Scripts Price History 1.1.0','pot-creation-date'=>'2026-10-16T16:37:09+00:00','po-revision-date'=>'2026-10-10 12:00+0300','x-generator'=>'WP-CLI 2.12.0','messages'=>['PN Scripts Price History for Discounts'=>'PN Scripts Price History dla promocji','https://pnscripts.com/marketplace/pnscripts-price-history'=>'https://pnscripts.com/marketplace/pnscripts-price-history','Records every product and variation price change and shows the lowest price in the 30 days before a discount (EU Price Indication Directive, Art. 6a). Shows nothing when the history is incomplete.'=>'Zapisuje każdą zmianę ceny produktów i wariantów oraz pokazuje najniższą cenę z 30 dni przed obniżką (dyrektywa w sprawie podawania cen, art. 6a). Nie pokazuje niczego, gdy historia jest niepełna.','PN Scripts'=>'PN Scripts','https://pnscripts.com'=>'https://pnscripts.com','Perishable goods'=>'Towary szybko psujące się','Products in this category perish or expire quickly. Only used when the perishable-goods exemption is enabled in the Price History settings.'=>'Produkty z tej kategorii szybko się psują lub mają krótki termin przydatności. Używane tylko wtedy, gdy w ustawieniach Price History włączono wyłączenie dla towarów szybko psujących się.','Products in this category perish or expire quickly.'=>'Produkty z tej kategorii szybko się psują lub mają krótki termin przydatności.','Shown'=>'Wyświetlana','Not on sale'=>'Bez promocji','Exempt'=>'Wyłączony','Unknown, hidden'=>'Nieznana, ukryta','No price history has been recorded yet.'=>'Nie zapisano jeszcze historii cen.','Prices during part of the period are unknown (the plugin was inactive or prices were changed outside WooCommerce).'=>'Ceny z części okresu są nieznane (wtyczka była nieaktywna albo ceny zmieniono poza WooCommerce).','The recorded history does not cover the whole period before the discount yet.'=>'Zapisana historia nie obejmuje jeszcze całego okresu przed obniżką.','The product was launched less than the period before the discount and the current rules hide the notice for such products.'=>'Produkt jest w sprzedaży krócej niż okres przed obniżką, a obecne zasady ukrywają informację dla takich produktów.','The product was already on sale when recording started, so the start of the discount is unknown.'=>'Produkt był już w promocji, gdy rozpoczęto zapisywanie, więc początek obniżki jest nieznany.','There is no price before the discount (the product was launched on sale or had no price).'=>'Brak ceny przed obniżką (produkt od początku był w promocji albo nie miał ceny).','WooCommerce shows a discount that is not in the recorded prices (for example a price changed by another plugin on the fly).'=>'WooCommerce pokazuje obniżkę, której nie ma w zapisanych cenach (np. cena zmieniana na bieżąco przez inną wtyczkę).','Marked as perishable and the perishable-goods exemption is enabled.'=>'Oznaczony jako szybko psujący się, a wyłączenie dla towarów szybko psujących się jest włączone.','Variable and grouped products are evaluated per variation or child product.'=>'Produkty z wariantami i produkty grupowe są oceniane osobno dla każdego wariantu lub produktu podrzędnego.','The tax settings or rates changed during the period, so earlier prices cannot be converted with today\'s taxes.'=>'Ustawienia lub stawki podatku zmieniły się w tym okresie, więc wcześniejszych cen nie można przeliczyć według dzisiejszych podatków.','Product editor'=>'Edytor produktu','Quick edit'=>'Szybka edycja','Bulk edit'=>'Edycja masowa','CSV import'=>'Import CSV','REST API'=>'REST API','WP-CLI'=>'WP-CLI','Background task'=>'Zadanie w tle','Scheduled sale'=>'Zaplanowana promocja','AJAX'=>'AJAX','Code'=>'Kod','First record'=>'Pierwszy zapis','After inactivity'=>'Po okresie nieaktywności','Repair'=>'Naprawa','Imported (Omnibus by iWorks)'=>'Zaimportowano (Omnibus od iWorks)','Imported (WC Price History)'=>'Zaimportowano (WC Price History)','Imported (Omnibus by iLabs)'=>'Zaimportowano (Omnibus by iLabs)','Your records'=>'Twoje dane','Price history and lowest prior price'=>'Historia cen i najniższa cena sprzed obniżki','Recorded automatically on every price change. This plugin helps display prices; you remain responsible for compliance.'=>'Zapisywana automatycznie przy każdej zmianie ceny. Wtyczka pomaga wyświetlać ceny; odpowiedzialność za zgodność z przepisami pozostaje po Twojej stronie.','No variations yet.'=>'Brak wariantów.','Grouped products have no own price; see each child product.'=>'Produkty grupowe nie mają własnej ceny; sprawdź poszczególne produkty podrzędne.','No prices recorded yet.'=>'Nie zapisano jeszcze żadnych cen.','From'=>'Od','Regular'=>'Regularna','Sale'=>'Promocyjna','Sale schedule'=>'Okres promocji','Price'=>'Cena','Source'=>'Źródło','Prices as entered in the shop (before the tax display setting). Newest first, up to 30 rows.'=>'Ceny w postaci wprowadzonej w sklepie (przed ustawieniem wyświetlania podatku). Najnowsze na górze, maks. 30 wierszy.','Add a price from your own records'=>'Dodaj cenę z własnych danych','For the time before this plugin started recording this product (%s): the price that applied from a day until the next row. Add one row for the regular price and one for the day the current discount started. You are responsible for these prices; keep the records they come from.'=>'Dla okresu sprzed rozpoczęcia zapisywania tego produktu przez wtyczkę (%s): cena obowiązująca od danego dnia do następnego wiersza. Dodaj jeden wiersz z ceną regularną i jeden z dniem rozpoczęcia obecnej obniżki. Odpowiadasz za te ceny; zachowaj dokumenty, z których pochodzą.','The price that applied from a day until the next row. You are responsible for these prices; keep the records they come from.'=>'Cena obowiązująca od danego dnia do następnego wiersza. Odpowiadasz za te ceny; zachowaj dokumenty, z których pochodzą.','Regular price'=>'Cena regularna','Sale price (optional)'=>'Cena promocyjna (opcjonalnie)','Saved when you update the product. Many products at once: WooCommerce → Price History → Import and tools.'=>'Zapisywane przy aktualizacji produktu. Wiele produktów naraz: WooCommerce → Price History → Import i narzędzia.','A price from your records was removed.'=>'Usunięto cenę z Twoich danych.','The price from your records was added to the price history.'=>'Cenę z Twoich danych dodano do historii cen.','Price History:'=>'Price History:','(unknown before)'=>'(wcześniej nieznana)','Remove'=>'Usuń','lowest price in the %1$d days before the discount that started on %2$s:'=>'najniższa cena z %1$d dni przed obniżką rozpoczętą %2$s:','Goods that perish or expire quickly. Only used when the perishable-goods exemption is enabled in the Price History settings.'=>'Towary, które szybko się psują lub mają krótki termin przydatności. Używane tylko wtedy, gdy w ustawieniach Price History włączono wyłączenie dla towarów szybko psujących się.','Price History: lowest price in the 30 days before a discount'=>'Price History: najniższa cena z 30 dni przed obniżką','Price History'=>'Price History','Settings'=>'Ustawienia','Sorry, you are not allowed to access this page.'=>'Nie masz uprawnień do tej strony.','Coverage report'=>'Raport pokrycia','Import and tools'=>'Import i narzędzia','Price History: lowest price before a discount'=>'Price History: najniższa cena przed obniżką','This plugin helps display prices; you remain responsible for compliance. It does not give legal advice. Check the rules that apply to your shop.'=>'Wtyczka pomaga wyświetlać ceny; odpowiedzialność za zgodność z przepisami pozostaje po Twojej stronie. Wtyczka nie udziela porad prawnych. Sprawdź przepisy, które dotyczą Twojego sklepu.','The action could not be started. Action Scheduler (part of WooCommerce) is not available.'=>'Nie udało się uruchomić działania. Action Scheduler (część WooCommerce) jest niedostępny.','Started in the background. Refresh this page to see the progress.'=>'Uruchomiono w tle. Odśwież stronę, aby zobaczyć postęp.','Rules'=>'Zasady','Preset'=>'Ustawienia wstępne','A preset fills the three rules below when you save. Presets are starting points, not legal advice: confirm the rules of the country you sell to. Choose "Custom rules" to set them yourself.'=>'Ustawienia wstępne wypełniają trzy poniższe zasady przy zapisie. To punkt wyjścia, a nie porada prawna: sprawdź przepisy kraju, w którym sprzedajesz. Wybierz „Własne zasady”, aby ustawić je samodzielnie.','Period before the discount (days)'=>'Okres przed obniżką (dni)','At least 30 days. The period ends when the current discount started and begins at midnight that many days earlier. For progressive discounts it ends when the first discount started.'=>'Co najmniej 30 dni. Okres kończy się w chwili rozpoczęcia bieżącej obniżki i zaczyna o północy odpowiednią liczbę dni wcześniej. Przy obniżkach stopniowych kończy się w chwili rozpoczęcia pierwszej obniżki.','Products on the market for less than the period'=>'Produkty w sprzedaży krócej niż okres','Hide the notice (strict)'=>'Ukryj informację (ściśle)','Use the lowest price since the product was launched (only where your country allows a shorter period)'=>'Użyj najniższej ceny od rozpoczęcia sprzedaży produktu (tylko gdy przepisy Twojego kraju dopuszczają krótszy okres)','Do not show the notice for products (or categories) marked as perishable. Only where your country exempts perishable goods.'=>'Nie pokazuj informacji dla produktów (lub kategorii) oznaczonych jako szybko psujące się. Tylko gdy przepisy Twojego kraju zwalniają towary szybko psujące się.','Display'=>'Wyświetlanie','Product page'=>'Strona produktu','Show the notice under the price on product pages (classic templates and the Product Price block).'=>'Pokazuj informację pod ceną na stronach produktów (klasyczne szablony i blok „Cena produktu”).','Shop and category pages'=>'Strony sklepu i kategorii','Show the notice in product lists, related products and product blocks.'=>'Pokazuj informację na listach produktów, w produktach powiązanych i w blokach produktów.','Variations'=>'Warianty','Show the notice for the selected variation of variable products.'=>'Pokazuj informację dla wybranego wariantu produktów z wariantami.','Incomplete history'=>'Niepełna historia','Hide the notice when the price history does not cover the whole period (recommended). When unchecked, the text below is shown instead.'=>'Ukryj informację, gdy historia cen nie obejmuje całego okresu (zalecane). Gdy pole jest odznaczone, zamiast niej wyświetlany jest poniższy tekst.','Notice text'=>'Treść informacji','Notice text (period since launch)'=>'Treść informacji (okres od rozpoczęcia sprzedaży)','Text when the history is incomplete'=>'Tekst przy niepełnej historii','Placeholders'=>'Symbole zastępcze','{price} the lowest price, {days} the number of days, {date} the day the discount started. Leave a text empty to use the translated default.'=>'{price} najniższa cena, {days} liczba dni, {date} dzień rozpoczęcia obniżki. Zostaw pole puste, aby użyć przetłumaczonego tekstu domyślnego.','To place the notice elsewhere, use the shortcode %s.'=>'Aby umieścić informację w innym miejscu, użyj shortcode’u %s.','Data'=>'Dane','Keep history for (days)'=>'Przechowuj historię przez (dni)','Older prices are deleted daily, except the ones still needed for a running discount. Minimum 31 days.'=>'Starsze ceny są usuwane codziennie, z wyjątkiem tych, które są potrzebne dla trwającej obniżki. Minimum 31 dni.','When recording starts for an existing product, assume its current price has applied since the product was last modified. Leave unchecked if other software changes prices without updating products (strict).'=>'Gdy zapisywanie zaczyna się dla istniejącego produktu, przyjmij, że jego obecna cena obowiązuje od ostatniej modyfikacji produktu. Pozostaw odznaczone, jeśli inne oprogramowanie zmienia ceny bez aktualizowania produktów (ściśle).','Uninstall'=>'Odinstalowanie','Delete the price history and settings when the plugin is deleted.'=>'Usuń historię cen i ustawienia podczas usuwania wtyczki.','%d product or variation is on sale.'=>'%d produkt lub wariant jest w promocji.' . "\0" . '%d produkty i warianty są w promocji.' . "\0" . '%d produktów i wariantów jest w promocji.','For each one: whether the lowest prior price is known and shown, and if not, why.'=>'Dla każdego z nich: czy najniższa cena sprzed obniżki jest znana i wyświetlana, a jeśli nie – dlaczego.','Product'=>'Produkt','Current price'=>'Aktualna cena','Lowest prior price'=>'Najniższa cena sprzed obniżki','Discount started'=>'Początek obniżki','Status'=>'Status','%1$d price records for %2$d products and variations.'=>'Zapisy cen: %1$d, produkty i warianty: %2$d.','Stored in one table of its own (%1$s, no posts or post meta); history older than %2$d days is deleted automatically, except prices a running discount still needs.'=>'Przechowywane we własnej tabeli (%1$s, bez wpisów i post meta); historia starsza niż %2$d dni jest usuwana automatycznie, z wyjątkiem cen potrzebnych trwającej obniżce.','Stored in one table of its own (no posts or post meta); history older than %d days is deleted automatically, except prices a running discount still needs.'=>'Przechowywane we własnej tabeli (bez wpisów i post meta); historia starsza niż %d dni jest usuwana automatycznie, z wyjątkiem cen potrzebnych trwającej obniżce.','Last catalogue check finished %1$s: %2$d products checked, %3$d records added.'=>'Ostatnie sprawdzenie katalogu zakończone %1$s: sprawdzono produktów: %2$d, dodano zapisów: %3$d.','Catalogue check running: %d products checked so far.'=>'Trwa sprawdzanie katalogu: dotąd sprawdzono produktów: %d.','Check the catalogue'=>'Sprawdzanie katalogu','Records the current price of products that have no history yet, and marks products whose price changed without passing through WooCommerce. Runs in the background.'=>'Zapisuje bieżącą cenę produktów, które nie mają jeszcze historii, i oznacza produkty, których cena zmieniła się z pominięciem WooCommerce. Działa w tle.','Check the catalogue now'=>'Sprawdź katalog teraz','Import history from another plugin'=>'Import historii z innej wtyczki','Reads (never changes) the price history saved by another plugin and adds the prices from before this plugin started recording each product. Only import from a plugin that was active until now; a plugin that was switched off long ago has gaps that cannot be detected. Running an import twice is safe.'=>'Odczytuje (nigdy nie zmienia) historię cen zapisaną przez inną wtyczkę i dodaje ceny sprzed rozpoczęcia zapisu każdego produktu przez tę wtyczkę. Importuj tylko z wtyczki, która była aktywna do teraz; wtyczka wyłączona dawno temu ma luki, których nie da się wykryć. Ponowny import jest bezpieczny.','Plugin'=>'Wtyczka','Data found'=>'Znalezione dane','Last import'=>'Ostatni import','%1$s: %2$d imported, %3$d skipped'=>'%1$s: zaimportowano %2$d, pominięto %3$d','Running…'=>'W toku…','Import'=>'Importuj','Background tasks'=>'Zadania w tle','Pending tasks: %d.'=>'Oczekujące zadania: %d.','View in WooCommerce → Status → Scheduled Actions'=>'Zobacz w WooCommerce → Status → Zaplanowane działania','Add prices from your own records'=>'Dodaj ceny z własnych danych','Products that were already on sale when this plugin started recording show no notice until the history covers the whole period. If your shop system, accounting or price lists show which prices applied before, upload them here: each line is the price that applied from a day until the next line of the same product. Lines dated after the plugin started recording a product are refused, so the recorded history always wins. You are responsible for these prices; keep the records they come from.'=>'Produkty, które były już w promocji, gdy wtyczka zaczęła zapisywać ceny, nie pokazują informacji, dopóki historia nie obejmie całego okresu. Jeśli system sklepu, księgowość lub cenniki pokazują, jakie ceny obowiązywały wcześniej, prześlij je tutaj: każdy wiersz to cena obowiązująca od danego dnia do następnego wiersza tego samego produktu. Wiersze z datą po rozpoczęciu zapisywania produktu są odrzucane, więc zapisana historia zawsze ma pierwszeństwo. Odpowiadasz za te ceny; zachowaj dokumenty, z których pochodzą.','CSV columns: product ID or SKU, date (YYYY-MM-DD), regular price, sale price (empty when there was no sale). A header line is allowed. Example:'=>'Kolumny CSV: ID lub SKU produktu, data (RRRR-MM-DD), cena regularna, cena promocyjna (puste, gdy nie było promocji). Dozwolony wiersz nagłówka. Przykład:','Prices added: %1$d; lines not added: %2$d.'=>'Dodane ceny: %1$d; niedodane wiersze: %2$d.','Line %1$d (%2$s): %3$s'=>'Wiersz %1$d (%2$s): %3$s','CSV file'=>'Plik CSV','Upload and add prices'=>'Prześlij i dodaj ceny','Also on the product edit screen (one product) and with WP-CLI: wp pnscripts-price-history import-records file.csv'=>'Również na ekranie edycji produktu (jeden produkt) i przez WP-CLI: wp pnscripts-price-history import-records file.csv','Sorry, you are not allowed to do that.'=>'Nie masz uprawnień do wykonania tej czynności.','Lowest price in the {days} days before the discount: {price}'=>'Najniższa cena z {days} dni przed obniżką: {price}','Lowest price since this product was launched ({days} days) before the discount: {price}'=>'Najniższa cena od rozpoczęcia sprzedaży produktu ({days} dni) przed obniżką: {price}','The lowest price in the {days} days before the discount is not available.'=>'Najniższa cena z {days} dni przed obniżką jest niedostępna.','Omnibus — show the lowest price (by iWorks)'=>'Omnibus — show the lowest price (od iWorks)','WC Price History for Omnibus'=>'WC Price History for Omnibus','Omnibus by iLabs'=>'Omnibus by iLabs','PN Scripts Price History needs WooCommerce %s or newer to be active.'=>'PN Scripts Price History wymaga aktywnej wtyczki WooCommerce w wersji %s lub nowszej.','The date must be a real day written as YYYY-MM-DD.'=>'Data musi być istniejącym dniem w formacie RRRR-MM-DD.','The date is in the future.'=>'Data jest w przyszłości.','The plugin was already recording this product on that day; its own history is kept and cannot be overwritten.'=>'Tego dnia wtyczka już zapisywała ten produkt; jej własna historia jest zachowana i nie można jej nadpisać.','The regular price is missing or not a number (write 1299.90 or 1299,90, without thousands separators).'=>'Brak ceny regularnej lub nie jest liczbą (wpisz 1299.90 lub 1299,90, bez separatorów tysięcy).','The sale price is not a number (write 1299.90 or 1299,90, without thousands separators).'=>'Cena promocyjna nie jest liczbą (wpisz 1299.90 lub 1299,90, bez separatorów tysięcy).','The sale price must be lower than the regular price.'=>'Cena promocyjna musi być niższa od regularnej.','A price from your records already exists for that day.'=>'Dla tego dnia istnieje już cena z Twoich danych.','No product or variation with this ID or SKU.'=>'Brak produktu lub wariantu o tym ID lub SKU.','Variable and grouped products have no own price; enter the price of each variation or child product.'=>'Produkty zmienne i grupowe nie mają własnej ceny; wpisz cenę każdego wariantu lub produktu podrzędnego.','No CSV file was received, or it is larger than 2 MB.'=>'Nie otrzymano pliku CSV lub jest większy niż 2 MB.','The price could not be saved.'=>'Nie udało się zapisać ceny.','EU, strict: 30 days, no optional exemptions'=>'UE, ściśle: 30 dni, bez opcjonalnych wyłączeń','Bulgaria: 30 days, no optional exemptions'=>'Bułgaria: 30 dni, bez opcjonalnych wyłączeń','Germany: 30 days, perishable goods may be excluded'=>'Niemcy: 30 dni, towary szybko psujące się mogą być wyłączone','Poland: 30 days, products offered for less than 30 days use the period since launch'=>'Polska: 30 dni, dla produktów oferowanych krócej niż 30 dni stosuje się okres od rozpoczęcia sprzedaży','Custom rules'=>'Własne zasady']];